-- RRC082: MariaDB10.11, dedicated fresh admin session; manual coordinated application only.
-- Source recipe facts/provenance: batch.public.json. No engine/updater/version/rule changes.
-- Anonymous compound block: no permanent helper procedure or migration table.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE already_present INT DEFAULT 0;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 requires fresh transaction-free session'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 strict SQL mode required'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tradeskill_recipe','tradeskill_recipe_entries','items') AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc082_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc082_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc082_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 START TRANSACTION;
 SET own_transaction=TRUE;
 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO already_present FROM tradeskill_recipe r JOIN rrc082_recipes e ON r.id=e.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rrc082_items e LEFT JOIN items i ON i.id=e.id WHERE i.id IS NULL OR BINARY i.Name<>BINARY e.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 item identity/dependency mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=41555 AND itemclass=1 AND bagtype=11 AND bagslots=10 AND bagsize=3 AND classes=33089)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 native kit mismatch'; END IF; IF (SELECT COUNT(*) FROM items WHERE (id=115159 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=16384) OR (id=90316 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=93542 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=41544 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=93521 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=41536 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=115178 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=32768) OR (id=93555 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93580 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=41525 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=41534 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=90312 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=115184 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=32768) OR (id=90314 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=93561 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=115187 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=32768) OR (id=93588 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=90315 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=115193 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=93575 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93553 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=90313 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=41529 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=115196 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=32768) OR (id=115199 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=32768) OR (id=93587 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=93578 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=116098 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=256) OR (id=93590 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=41527 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=93540 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=116116 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=256) OR (id=41539 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=116119 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=256) OR (id=116122 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=256) OR (id=41535 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=116128 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=256) OR (id=93589 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=116134 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=256) OR (id=41540 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=41538 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=41537 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=116346 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=1) OR (id=93579 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=41528 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=33089) OR (id=93554 AND size=0 AND stackable=1 AND maxcharges=0 AND classes=15360) OR (id=116358 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=1) OR (id=116361 AND size=1 AND stackable=1 AND maxcharges=0 AND classes=1) OR (id=116376 AND size=1 AND stackable=0 AND maxcharges=0 AND classes=1))<>49 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 input/output semantics mismatch'; END IF; IF (SELECT COUNT(*) FROM items WHERE (id=115159 AND itemtype=20 AND scrolleffect=14159 AND scrolllevel=0 AND reqlevel=0) OR (id=115178 AND itemtype=20 AND scrolleffect=14178 AND scrolllevel=0 AND reqlevel=0) OR (id=115184 AND itemtype=20 AND scrolleffect=14184 AND scrolllevel=0 AND reqlevel=0) OR (id=115187 AND itemtype=20 AND scrolleffect=14187 AND scrolllevel=0 AND reqlevel=0) OR (id=115193 AND itemtype=20 AND scrolleffect=14193 AND scrolllevel=0 AND reqlevel=0) OR (id=115196 AND itemtype=20 AND scrolleffect=14196 AND scrolllevel=0 AND reqlevel=0) OR (id=115199 AND itemtype=20 AND scrolleffect=14199 AND scrolllevel=0 AND reqlevel=0) OR (id=116098 AND itemtype=20 AND scrolleffect=15098 AND scrolllevel=0 AND reqlevel=0) OR (id=116116 AND itemtype=20 AND scrolleffect=15116 AND scrolllevel=0 AND reqlevel=0) OR (id=116119 AND itemtype=20 AND scrolleffect=15119 AND scrolllevel=0 AND reqlevel=0) OR (id=116122 AND itemtype=20 AND scrolleffect=15122 AND scrolllevel=0 AND reqlevel=0) OR (id=116128 AND itemtype=20 AND scrolleffect=15128 AND scrolllevel=0 AND reqlevel=0) OR (id=116134 AND itemtype=20 AND scrolleffect=15134 AND scrolllevel=0 AND reqlevel=0) OR (id=116346 AND itemtype=20 AND scrolleffect=15346 AND scrolllevel=0 AND reqlevel=0) OR (id=116358 AND itemtype=20 AND scrolleffect=15358 AND scrolllevel=0 AND reqlevel=0) OR (id=116361 AND itemtype=20 AND scrolleffect=15361 AND scrolllevel=0 AND reqlevel=0) OR (id=116376 AND itemtype=20 AND scrolleffect=15376 AND scrolllevel=0 AND reqlevel=0))<>17 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 Tome spell binding mismatch'; END IF;
 IF already_present<>17 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 rollback requires exact whole installed batch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc082_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 recipe postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc082_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 expected entry absent'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc082_recipes q ON q.id=r.recipe_id LEFT JOIN rrc082_entries e ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 foreign/different target entries'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc082_recipes q ON q.id=r.recipe_id)<>126 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 target entry multiplicity mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM char_recipe_list c JOIN rrc082_recipes e ON c.recipe_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 rollback refused: learned recipe references exist'; END IF;
 DELETE r FROM tradeskill_recipe_entries r JOIN rrc082_recipes e ON r.recipe_id=e.id;
 DELETE r FROM tradeskill_recipe r JOIN rrc082_recipes e ON r.id=e.id;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before-17 OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before-126 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC082 rollback count mismatch'; END IF;
 DROP TEMPORARY TABLE rrc082_entries;
 DROP TEMPORARY TABLE rrc082_recipes;
 DROP TEMPORARY TABLE rrc082_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC082' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
